PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS finance_periods(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,starts_on TEXT,ends_on TEXT,due_on TEXT,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS charge_rules(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,period_id TEXT REFERENCES finance_periods(id) ON DELETE SET NULL,title TEXT NOT NULL,basis TEXT NOT NULL,fixed_amount INTEGER NOT NULL DEFAULT 0,formula_json TEXT,owner_share REAL,resident_share REAL,is_recurring INTEGER NOT NULL DEFAULT 0,created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS charge_invoices(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,period_id TEXT REFERENCES finance_periods(id) ON DELETE SET NULL,unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE,payer_type TEXT NOT NULL DEFAULT 'resident',title TEXT NOT NULL,amount INTEGER NOT NULL,due_on TEXT,status TEXT NOT NULL DEFAULT 'issued',created_at TEXT NOT NULL,updated_at TEXT,UNIQUE(period_id,unit_id,payer_type,title));
CREATE TABLE IF NOT EXISTS finance_accounts(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,code TEXT NOT NULL,title TEXT NOT NULL,account_type TEXT NOT NULL,parent_id TEXT REFERENCES finance_accounts(id) ON DELETE SET NULL,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(building_id,code));
CREATE TABLE IF NOT EXISTS finance_transactions(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,period_id TEXT REFERENCES finance_periods(id) ON DELETE SET NULL,transaction_type TEXT NOT NULL,transaction_date TEXT NOT NULL,reference_number TEXT,description TEXT NOT NULL,amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS finance_transaction_lines(id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL REFERENCES finance_transactions(id) ON DELETE CASCADE,account_id TEXT NOT NULL REFERENCES finance_accounts(id),debit INTEGER NOT NULL DEFAULT 0,credit INTEGER NOT NULL DEFAULT 0,memo TEXT);
CREATE TABLE IF NOT EXISTS payment_receipts(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE,invoice_id TEXT REFERENCES charge_invoices(id) ON DELETE SET NULL,amount INTEGER NOT NULL,method TEXT NOT NULL,tracking_code TEXT,paid_at TEXT NOT NULL,proof_document_id TEXT,status TEXT NOT NULL DEFAULT 'pending',reviewed_by TEXT REFERENCES people(id) ON DELETE SET NULL,reviewed_at TEXT,review_note TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS building_budgets(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,fiscal_year TEXT NOT NULL,title TEXT NOT NULL,approved_amount INTEGER NOT NULL DEFAULT 0,actual_amount INTEGER NOT NULL DEFAULT 0,account_id TEXT REFERENCES finance_accounts(id) ON DELETE SET NULL,owner_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS service_requests(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,requester_id TEXT REFERENCES people(id) ON DELETE SET NULL,category TEXT NOT NULL,subject TEXT NOT NULL,description TEXT,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'submitted',assigned_to TEXT REFERENCES people(id) ON DELETE SET NULL,due_at TEXT,resolved_at TEXT,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS service_request_updates(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES service_requests(id) ON DELETE CASCADE,actor_id TEXT REFERENCES people(id) ON DELETE SET NULL,body TEXT NOT NULL,status TEXT,is_internal INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS building_assets(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,asset_code TEXT NOT NULL,title TEXT NOT NULL,category TEXT,location TEXT,manufacturer TEXT,model TEXT,serial_number TEXT,purchased_on TEXT,warranty_until TEXT,value_amount INTEGER,condition_status TEXT NOT NULL DEFAULT 'active',document_id TEXT,created_at TEXT NOT NULL,updated_at TEXT,UNIQUE(building_id,asset_code));
CREATE TABLE IF NOT EXISTS maintenance_plans(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,asset_id TEXT REFERENCES building_assets(id) ON DELETE SET NULL,title TEXT NOT NULL,frequency TEXT NOT NULL,last_service_on TEXT,next_due_on TEXT NOT NULL,vendor_id TEXT,checklist_json TEXT,status TEXT NOT NULL DEFAULT 'scheduled',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS maintenance_jobs(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,plan_id TEXT REFERENCES maintenance_plans(id) ON DELETE SET NULL,asset_id TEXT REFERENCES building_assets(id) ON DELETE SET NULL,vendor_id TEXT,title TEXT NOT NULL,description TEXT,scheduled_at TEXT,completed_at TEXT,cost_amount INTEGER,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS building_vendors(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,name TEXT NOT NULL,specialty TEXT,contact_name TEXT,phone TEXT,email TEXT,contract_reference TEXT,insurance_status TEXT,rating REAL,notes TEXT,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS building_contracts(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,vendor_id TEXT REFERENCES building_vendors(id) ON DELETE SET NULL,title TEXT NOT NULL,contract_number TEXT,starts_on TEXT,ends_on TEXT,amount INTEGER,renewal_notice_days INTEGER,status TEXT NOT NULL DEFAULT 'active',document_id TEXT,created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS building_staff(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,person_id TEXT REFERENCES people(id) ON DELETE SET NULL,full_name TEXT NOT NULL,job_title TEXT NOT NULL,phone TEXT,shift_pattern TEXT,base_salary INTEGER,insurance_status TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS payroll_entries(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,staff_id TEXT NOT NULL REFERENCES building_staff(id) ON DELETE CASCADE,period_label TEXT NOT NULL,base_amount INTEGER NOT NULL DEFAULT 0,overtime_hours REAL NOT NULL DEFAULT 0,overtime_amount INTEGER NOT NULL DEFAULT 0,benefits_amount INTEGER NOT NULL DEFAULT 0,deductions_amount INTEGER NOT NULL DEFAULT 0,net_amount INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,sku TEXT,title TEXT NOT NULL,category TEXT,quantity REAL NOT NULL DEFAULT 0,minimum_quantity REAL NOT NULL DEFAULT 0,unit_label TEXT,storage_location TEXT,created_at TEXT NOT NULL,updated_at TEXT,UNIQUE(building_id,sku));
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES inventory_items(id) ON DELETE CASCADE,movement_type TEXT NOT NULL,quantity REAL NOT NULL,reference_number TEXT,description TEXT,actor_id TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parking_spaces(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,space_number TEXT NOT NULL,level_label TEXT,space_type TEXT NOT NULL DEFAULT 'private',status TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL,UNIQUE(building_id,space_number));
CREATE TABLE IF NOT EXISTS vehicle_registrations(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,parking_space_id TEXT REFERENCES parking_spaces(id) ON DELETE SET NULL,plate_number TEXT NOT NULL,owner_name TEXT,valid_from TEXT,valid_until TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visitor_logs(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,visitor_name TEXT NOT NULL,plate_number TEXT,purpose TEXT,entered_at TEXT NOT NULL,exited_at TEXT,guard_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'inside',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parcel_logs(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE,recipient_name TEXT NOT NULL,sender_name TEXT,tracking_code TEXT,received_at TEXT NOT NULL,received_by TEXT REFERENCES people(id) ON DELETE SET NULL,delivered_at TEXT,delivered_to TEXT,status TEXT NOT NULL DEFAULT 'received',notes TEXT);
CREATE TABLE IF NOT EXISTS facility_resources(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,category TEXT,capacity INTEGER,fee_amount INTEGER NOT NULL DEFAULT 0,slot_rules_json TEXT,booking_rules_json TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS facility_reservations(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,resource_id TEXT NOT NULL REFERENCES facility_resources(id) ON DELETE CASCADE,unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,attendee_count INTEGER,fee_amount INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS building_announcements(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,category TEXT,audience_rule_json TEXT,publish_at TEXT,expires_at TEXT,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS building_meetings(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,starts_at TEXT NOT NULL,location TEXT,agenda TEXT,quorum_status TEXT,minutes TEXT,status TEXT NOT NULL DEFAULT 'planned',created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_resolutions(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES building_meetings(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,assigned_to TEXT REFERENCES people(id) ON DELETE SET NULL,due_at TEXT,status TEXT NOT NULL DEFAULT 'open',completed_at TEXT);
CREATE TABLE IF NOT EXISTS building_polls(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,audience_rule_json TEXT,poll_type TEXT NOT NULL DEFAULT 'survey',opens_at TEXT,closes_at TEXT,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS poll_options(id TEXT PRIMARY KEY,poll_id TEXT NOT NULL REFERENCES building_polls(id) ON DELETE CASCADE,label TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS poll_votes(id TEXT PRIMARY KEY,poll_id TEXT NOT NULL REFERENCES building_polls(id) ON DELETE CASCADE,option_id TEXT NOT NULL REFERENCES poll_options(id) ON DELETE CASCADE,person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,created_at TEXT NOT NULL,UNIQUE(poll_id,person_id));
CREATE TABLE IF NOT EXISTS building_documents(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,title TEXT NOT NULL,category TEXT,document_number TEXT,issued_on TEXT,expires_on TEXT,access_scope TEXT NOT NULL DEFAULT 'management',storage_key TEXT,uploaded_by TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS building_incidents(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,location TEXT NOT NULL,severity TEXT NOT NULL,reported_at TEXT NOT NULL,reporter_id TEXT REFERENCES people(id) ON DELETE SET NULL,immediate_action TEXT,assigned_to TEXT REFERENCES people(id) ON DELETE SET NULL,resolution TEXT,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meter_readings(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,meter_code TEXT NOT NULL,meter_type TEXT NOT NULL,read_at TEXT NOT NULL,previous_value REAL NOT NULL,current_value REAL NOT NULL,cost_amount INTEGER,notes TEXT,created_at TEXT NOT NULL,CHECK(current_value>=previous_value));
CREATE INDEX IF NOT EXISTS idx_finance_periods_building ON finance_periods(building_id,starts_on);
CREATE INDEX IF NOT EXISTS idx_charge_invoices_unit ON charge_invoices(unit_id,status,due_on);
CREATE INDEX IF NOT EXISTS idx_finance_transactions_building ON finance_transactions(building_id,transaction_date);
CREATE INDEX IF NOT EXISTS idx_payment_receipts_unit ON payment_receipts(unit_id,status,paid_at);
CREATE INDEX IF NOT EXISTS idx_service_requests_building ON service_requests(building_id,status,priority,created_at);
CREATE INDEX IF NOT EXISTS idx_assets_building ON building_assets(building_id,condition_status);
CREATE INDEX IF NOT EXISTS idx_maintenance_due ON maintenance_plans(building_id,next_due_on,status);
CREATE INDEX IF NOT EXISTS idx_contract_expiry ON building_contracts(building_id,ends_on,status);
CREATE INDEX IF NOT EXISTS idx_visitor_logs_building ON visitor_logs(building_id,entered_at,status);
CREATE INDEX IF NOT EXISTS idx_parcel_logs_unit ON parcel_logs(unit_id,status,received_at);
CREATE INDEX IF NOT EXISTS idx_reservations_resource ON facility_reservations(resource_id,starts_at,ends_at,status);
CREATE INDEX IF NOT EXISTS idx_announcements_publish ON building_announcements(building_id,status,publish_at);
CREATE INDEX IF NOT EXISTS idx_meetings_building ON building_meetings(building_id,starts_at);
CREATE INDEX IF NOT EXISTS idx_documents_expiry ON building_documents(building_id,expires_on);
CREATE INDEX IF NOT EXISTS idx_incidents_building ON building_incidents(building_id,status,severity);
CREATE INDEX IF NOT EXISTS idx_meter_readings_building ON meter_readings(building_id,meter_code,read_at);
